                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_packing_slip_unknown_order(shop):
    response = shop.fulfilment.handle_packing_slip("ord-9999")
    assert response.status == 404
    assert response.body == {"error": "order not found"}


def test_packing_slip_cancelled_order(shop):
    order_response = order(shop, "c1", ("BOOK", 1))
    order_id = order_response.body["order_id"]
    shop.orders.handle_cancel(order_id)

    response = shop.fulfilment.handle_packing_slip(order_id)
    assert response.status == 409
    assert "cancelled" in response.body["error"]


def test_packing_slip_valid_order(shop):
    order_response = order(shop, "c1", ("BOOK", 2), ("PEN", 1))
    order_id = order_response.body["order_id"]

    response = shop.fulfilment.handle_packing_slip(order_id)
    assert response.status == 200
    assert response.body["order_id"] == order_id
    assert response.body["customer_name"] == "Ada"
    assert response.body["lines"] == [
        {"sku": "BOOK", "name": "Book", "quantity": 2},
        {"sku": "PEN", "name": "Pen", "quantity": 1},
    ]


def test_packing_slip_preserves_line_order(shop):
    order_response = order(shop, "c2", ("PEN", 3), ("LAMP", 1), ("BOOK", 2))
    order_id = order_response.body["order_id"]

    response = shop.fulfilment.handle_packing_slip(order_id)
    assert response.status == 200
    assert response.body["lines"] == [
        {"sku": "PEN", "name": "Pen", "quantity": 3},
        {"sku": "LAMP", "name": "Lamp", "quantity": 1},
        {"sku": "BOOK", "name": "Book", "quantity": 2},
    ]


